import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"轮询 - October CMS - 3.x","titleTemplate":false,"description":"用于延迟加载和重复更新。","frontmatter":{"subtitle":"用于延迟加载和重复更新。"},"headers":[{"level":2,"title":"延迟加载请求","slug":"延迟加载请求","link":"#延迟加载请求","children":[]},{"level":2,"title":"轮询请求","slug":"轮询请求","link":"#轮询请求","children":[]},{"level":2,"title":"延迟加载部件","slug":"延迟加载部件","link":"#延迟加载部件","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/cms/features/polling.md","filePath":"3.x/zh-cn/cms/features/polling.md"}'),i={name:"3.x/zh-cn/cms/features/polling.md"};function k(r,a,g,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"轮询",-1)),s(p),a[1]||(a[1]=u(`<p>轮询是一种通过在请求元素上包含 <code>data-auto-submit</code> 属性来延迟或重复 AJAX 更新的技术。此功能应谨慎使用，因为在大规模使用时可能会增加服务器负载。为了缓解这一问题，该属性仅在用户的浏览器窗口处于活动状态时才会触发。</p><h2 id="延迟加载请求"><a href="#延迟加载请求" class="header-anchor">#</a> 延迟加载请求</h2><p>轮询请求通常与 <a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签</a>结合使用，因为它允许你自更新部件内容。以下是在页面上定义的 AJAX 处理程序，用于加载一些结果。假设这是一个开销较大的查询，我们可能希望在页面加载完成后再请求它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onFetchResults</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;results&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>下一步是在页面的某个位置包含一个名为 <strong>posts.htm</strong> 的 AJAX 启用部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在部件内部，如果 <code>results</code> 变量存在，内容将输出结果。否则，它会显示一条加载消息，并使用 <code>data-auto-submit</code> 请求作为二次请求来加载结果。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> results <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span>Found results<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> d<span class="token punctuation">(</span>results<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span>Loading the results...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onFetchResults<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-auto-submit</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="轮询请求"><a href="#轮询请求" class="header-anchor">#</a> 轮询请求</h2><p>对于需要重复请求以更新内容的场景，你可以将 <code>data-auto-submit</code> 设置为一个值（以毫秒为单位），以在延迟后执行自动请求。例如，一个使用 <code>{% ajaxPartial %}</code> 渲染的部件包含以下标记。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> launchDate <span class="token operator">=</span> carbon<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>2025-01-01<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> days <span class="token operator">=</span> launchDate<span class="token punctuation">.</span>diffInDays <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> hours <span class="token operator">=</span> launchDate<span class="token punctuation">.</span>subDays<span class="token punctuation">(</span>days<span class="token punctuation">)</span><span class="token punctuation">.</span>diffInHours <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> minutes <span class="token operator">=</span> launchDate<span class="token punctuation">.</span>subHours<span class="token punctuation">(</span>hours<span class="token punctuation">)</span><span class="token punctuation">.</span>diffInMinutes <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> seconds <span class="token operator">=</span> launchDate<span class="token punctuation">.</span>subMinutes<span class="token punctuation">(</span>minutes<span class="token punctuation">)</span><span class="token punctuation">.</span>diffInSeconds <span class="token delimiter punctuation">%}</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>
        Launch in...
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> days <span class="token delimiter punctuation">}}</span></span> days,
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hours <span class="token delimiter punctuation">}}</span></span> hours,
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> minutes <span class="token delimiter punctuation">}}</span></span> minutes,
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> seconds <span class="token delimiter punctuation">}}</span></span> seconds
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-auto-submit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>2000<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>此部件显示倒计时器，并包含一个 &quot;div&quot; 元素以自动更新自身。生成的更新也包含该元素，因此请求每 2 秒持续重复。</p><p>可以通过在后续请求中不包含该元素来停止轮询，例如，如果 <code>launchDone</code> 变量设置为 true，以下代码将停止轮询。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> <span class="token operator">not</span> launchDone <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-auto-submit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>2000<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="延迟加载部件"><a href="#延迟加载部件" class="header-anchor">#</a> 延迟加载部件</h2><p><code>data-auto-submit</code> 标签被 <code>{% ajaxPartial lazy %}</code> Twig 标签用于延迟加载部件。当页面首次渲染时，标记会自动包含以动态加载部件内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> lazy <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>查看 <a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签</a>了解更多信息。</p><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签</a></li></ul></div>`,20))])}const f=e(i,[["render",k]]);export{v as __pageData,f as default};
